test("validateAgainstSchema passes conforming payloads and flags every violation class", () => {
  // normalize line endings: git may check out CRLF (autocrlf), and the
  // extraction anchors below are LF-based
  const src = read("app.js").replace(/\r\n/g, "\n");
  const grab = (name) => {
    const s = src.indexOf(`function ${name}`);
    assert.ok(s !== -1, `${name} missing from bundle`);
    const e = src.indexOf("\n}\n", s);
    assert.ok(e > s, `${name} end not found`);
    return src.slice(s, e + 3);
  };
  // the validator calls mcpTypeName — extract both (they are self-contained)
  const validate = new Function(
    grab("mcpTypeName") + "\n" + grab("validateAgainstSchema") +
    "; return validateAgainstSchema;")();

  const schema = {
    type: "object", additionalProperties: false, required: ["q"],
    properties: {
      q: { type: "string", minLength: 1 },
      n: { type: "integer", minimum: 1, maximum: 10 },
      mode: { type: "string", enum: ["a", "b"] },
      code: { type: "string", pattern: "^[A-Z]{3}$" },
    },
  };

  const good = validate({ q: "hi", n: 5, mode: "a", code: "SFO" }, schema);
  assert.equal(good.ok, true, JSON.stringify(good.findings));

  const missing = validate({ n: 5 }, schema);
  assert.equal(missing.ok, false, "absent required field must fail");
  assert.ok(missing.findings.some((f) => f.path === "q" && !f.ok && f.actual === "(missing)"));

  assert.equal(validate({ q: "hi", n: 2.5 }, schema).ok, false, "non-integer must violate integer type");
  assert.equal(validate({ q: "hi", n: 99 }, schema).ok, false, "value above maximum must violate");
  assert.equal(validate({ q: "hi", mode: "z" }, schema).ok, false, "value outside enum must violate");
  assert.equal(validate({ q: "hi", code: "sfo" }, schema).ok, false, "pattern mismatch must violate");
  assert.equal(validate({ q: "" }, schema).ok, false, "minLength violation must fail");
  assert.equal(validate({ q: "hi", evil: 1 }, schema).ok, false, "additionalProperties:false must reject extras");
});

test("validateAgainstSchema handles nested objects, arrays and combinators", () => {
  const src = read("app.js").replace(/\r\n/g, "\n");
  const grab = (name) => {
    const s = src.indexOf(`function ${name}`);
    assert.ok(s !== -1, `${name} missing from bundle`);
    const e = src.indexOf("\n}\n", s);
    assert.ok(e > s, `${name} end not found`);
    return src.slice(s, e + 3);
  };
  const validate = new Function(
    grab("mcpTypeName") + "\n" + grab("validateAgainstSchema") +
    "; return validateAgainstSchema;")();

  const nested = {
    type: "object", required: ["filter"],
    properties: {
      filter: {
        type: "object", required: ["city"],
        properties: {
          city: { type: "string", minLength: 3 },
          limit: { type: "integer", minimum: 1, maximum: 50 },
        },
      },
      tags: { type: "array", items: { type: "string", enum: ["a", "b"] }, minItems: 1 },
      mode: { anyOf: [{ type: "string", enum: ["fast"] }, { type: "integer", minimum: 1 }] },
      scope: { allOf: [{ type: "string" }, { maxLength: 4 }] },
      level: { oneOf: [{ type: "integer" }, { type: "string", enum: ["auto"] }] },
    },
  };

  const good = validate({
    filter: { city: "TYO", limit: 10 }, tags: ["a", "b"],
    mode: "fast", scope: "home", level: 3,
  }, nested);
  assert.equal(good.ok, true, JSON.stringify(good.findings.filter((f) => !f.ok)));

  // nested object: wrong leaf type is reported at its qualified path
  const badLeaf = validate({ filter: { city: "TO", limit: 10 } }, nested);
  assert.equal(badLeaf.ok, false, "short nested string must fail");
  assert.ok(badLeaf.findings.some((f) => f.path === "filter.city" && !f.ok),
    "expected qualified path filter.city");

  // nested required missing
  const miss = validate({ filter: { limit: 5 } }, nested);
  assert.ok(miss.findings.some((f) => f.path === "filter.city" && !f.ok && f.actual === "(missing)"),
    "nested required miss must report filter.city");

  // array items: element violation points at the index
  const badItem = validate({ filter: { city: "TYO" }, tags: ["a", "z"] }, nested);
  assert.equal(badItem.ok, false, "enum-violating item must fail");
  assert.ok(badItem.findings.some((f) => f.path === "tags[1]" && !f.ok),
    "expected item path tags[1]");

  // minItems
  assert.equal(validate({ filter: { city: "TYO" }, tags: [] }, nested).ok, false,
    "empty array must violate minItems");

  // anyOf: one matching branch passes, none fails
  assert.equal(validate({ filter: { city: "TYO" }, mode: 5 }, nested).ok, true,
    "anyOf integer branch must pass");
  assert.equal(validate({ filter: { city: "TYO" }, mode: true }, nested).ok, false,
    "anyOf must reject when no branch matches");

  // allOf: both constraints apply (string AND max length)
  assert.equal(validate({ filter: { city: "TYO" }, scope: "home" }, nested).ok, true);
  assert.equal(validate({ filter: { city: "TYO" }, scope: "toolong" }, nested).ok, false,
    "allOf must enforce every branch");

  // oneOf: exactly one branch
  assert.equal(validate({ filter: { city: "TYO" }, level: "auto" }, nested).ok, true);
  assert.equal(validate({ filter: { city: "TYO" }, level: [1] }, nested).ok, false,
    "oneOf must reject when nothing matches");
});

test("live-vs-sim integrity: honest clock, no baseline mixing, no fabricated trends", () => {
  const app = read("app.js").replace(/\r\n/g, "\n");
  const html = read("index.html");

  // clock: date, time and zone must come from one Date in one zone —
  // the old code mixed toISOString() (UTC date) with toTimeString()
  // (local time) and labeled the result "UTC"
  assert.ok(!app.includes("toTimeString"), "clock must not mix local time-of-day into a differently-labeled zone");
  assert.ok(app.includes("CLOCK_ZONE"), "clock must derive its timezone label");

  // live snapshots must never add simulated baselines to real signals
  assert.ok(!app.includes("kpi.ipi = 1247 +"), "hardcoded IPI baseline leaked into live signal rendering");
  assert.ok(!app.includes("kpi.rev = 84921.55"), "hardcoded revenue baseline leaked into live signal rendering");
  assert.ok(!app.includes("kpi.anom = 318 +"), "hardcoded anomaly baseline leaked into live signal rendering");

  // fabricated trend percentages are gone from the bundle entirely
  for (const fake of [
    "▲ 4.7% vs. prior 24h",
    "▲ 1.9 pts — Web Bot Auth adoption",
    "▲ 12.4% — stealth engine campaigns",
    "▲ 32% YoY (in-the-wild)",
    "▲ 9.2% — Pay Per Crawl beta",
  ]) {
    assert.ok(!app.includes(fake), `fabricated trend line still shipped: ${fake}`);
  }

  // shared ledgers: sim row generators pause while a live capture is on
  assert.ok(app.includes("if (!liveMode) addMcpRow()"), "MCP sim rows must pause in live mode");
  assert.ok(app.includes("if (!liveMode) addIpiRow()"), "IPI sim rows must pause in live mode");
  // real rows announce themselves inside the SIM TrajAD console
  assert.ok(app.includes('"LIVE · " + sg.trajad'), "a real TrajAD signal must be marked LIVE inside the sim console");

  // honesty: the UI must not claim a Content-Digest verification the
  // server never performs (it enforces the ±120 s freshness window only)
  assert.ok(!html.includes("Verify Content-Digest"), "verification panel claims a digest check that does not exist");
  assert.ok(html.includes("Freshness window (±120 s)"), "step 4 must describe the freshness check that does happen");

  // the editorial ticker is always labeled SIM
  assert.ok(app.includes("class='dim'>SIM<"), "ticker must carry its SIM label");

  // duplicate SSE frames are dropped before any counter moves
  assert.ok(app.includes("seenEvents"), "event dedupe guard missing from the live feed");
});
